// Verify WP notifier signature: X-Siraj-Signature: v1=hex(HMAC-SHA256("<ts>.<rawBody>", secret))
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on self-hosted n8n [VERIFY on your version].
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.rawBody;
const ts = String(headers['x-siraj-timestamp'] ?? '');
const sig = String(headers['x-siraj-signature'] ?? '');
const secret = String($env.SIRAJ_N8N_SECRET ?? '');
const fail = (reason) => [{ json: { ok: false, reason } }];
if (!secret) return fail('SIRAJ_N8N_SECRET not set on this n8n instance');
if (!rawBody) return fail('raw body missing - enable Raw Body on the Webhook node');
if (!ts || !sig) return fail('missing signature headers');
const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
if (!Number.isFinite(Number(ts)) || skew > 300) return fail('timestamp missing or expired (skew ' + skew + 's)');
const expected = 'v1=' + crypto.createHmac('sha256', secret).update(ts + '.' + rawBody).digest('hex');
const a = Buffer.from(sig, 'utf8');
const b = Buffer.from(expected, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('bad signature');
let payload;
try { payload = JSON.parse(rawBody); } catch (e) { return fail('body is not JSON'); }
if (payload.event !== 'booking.created') return fail('unexpected event: ' + payload.event);
const bk = payload.booking || {};
// Defensive phone normalization (WP already stores +20...): expect +20(10|11|12|15)xxxxxxxx
const raw = String(bk.phone ?? '').replace(/[^\d+]/g, '');
const phone = raw.startsWith('+20') ? raw : raw.startsWith('0020') ? '+20' + raw.slice(4) : raw.startsWith('0') ? '+20' + raw.slice(1) : raw;
const phoneValid = /^\+20(10|11|12|15)\d{8}$/.test(phone);
const missing = ['name', 'phone', 'service_label', 'date'].filter((k) => !bk[k]);
if (missing.length) return fail('missing fields: ' + missing.join(','));
return [{ json: { ok: true, booking: { id: bk.id, name: bk.name, phone, phoneValid, service: bk.service, service_label: bk.service_label, date: bk.date, notes: bk.notes || '', created_at: bk.created_at || '' }, receivedAt: new Date().toISOString() } }];
